class Solution {
public:
    bool uniqueOccurrences(vector<int>& arr) {
        unordered_map<int,int> cnt;
        for (int x : arr) cnt[x]++;
        unordered_set<int> seen;
        for (auto& p : cnt) {
            if (seen.count(p.second)) return false;
            seen.insert(p.second);
        }
        return true;
    }
};
